// friday13.cs — Friday the 13th explorer (proleptic Gregorian calendar)

// Find the earliest Friday the 13th starting from 0001-01-01
DateTime earliest = DateTime.MinValue;
for (int year = 1; year <= 9999; year++)
{
    var d = new DateTime(year, 1, 13);
    for (int month = 1; month <= 12; month++)
    {
        d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            break;
        }
    }
    if (earliest != DateTime.MinValue) break;
}
Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest.DayOfWeek})");

// Count Friday the 13ths in one full 400-year Gregorian cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: distribution by month across the 400-year cycle
var byMonth = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            byMonth[month - 1]++;
    }
}
Console.WriteLine("\nDistribution by month:");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateTime(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");

